changeSet.sql:
ALTER TABLE outbox_events ADD CONSTRAINT ck_outbox_events_schema_version CHECK (schema_version >= 1);
ALTER TABLE outbox_events ADD CONSTRAINT ck_outbox_events_version CHECK (business_version >= 1);
ALTER TABLE outbox_events ADD CONSTRAINT ck_outbox_events_attempts CHECK (attempts >= 0);
ALTER TABLE outbox_events ADD CONSTRAINT ck_outbox_events_action CHECK (action IN
    ('CREATED','CONTENT_UPDATED','SUBMITTED','REVIEW_STARTED','APPROVED','REJECTED','PUBLISHED','ARCHIVED'));
ALTER TABLE outbox_events ADD CONSTRAINT ck_outbox_events_status CHECK (status IN
    ('Draft','Submitted','InReview','Approved','Rejected','Published','Archived'));
CREATE INDEX idx_outbox_events_pending ON outbox_events (occurred_at, id) WHERE published_at IS NULL;
